<?php
namespace Xdecaro\Component\Decarocourses\Administrator\Service;
defined('_JEXEC') or die;
use Joomla\CMS\Component\ComponentHelper; use Joomla\CMS\Factory; use Joomla\CMS\Log\Log; use Throwable;
final class CrossProductIntegrationService { public const COMPONENT='com_decarocourses'; public function notify(array $data):?int{if(!ComponentHelper::isEnabled('com_xdecaronotifications'))return null;$data['source_component']=self::COMPONENT;try{$c=Factory::getApplication()->bootComponent('com_xdecaronotifications');if(!is_object($c)||!method_exists($c,'getNotificationService'))return null;$s=$c->getNotificationService();return is_object($s)&&method_exists($s,'create')?(int)$s->create($data):null;}catch(Throwable $e){Log::add('Courses notification bridge: '.$e->getMessage(),Log::WARNING,'com_decarocourses.integration');return null;}} public function task(array $data,?array $assignee=null,int $actor=0):?int{if(!ComponentHelper::isEnabled('com_xdecarotasks'))return null;$data['source_component']=self::COMPONENT;try{$c=Factory::getApplication()->bootComponent('com_xdecarotasks');if(!is_object($c)||!method_exists($c,'getTaskService'))return null;$s=$c->getTaskService();$id=(int)$s->create($data,max(0,$actor));if($id>0&&$assignee&&method_exists($s,'assign')){$type=trim((string)($assignee['type']??''));$recipient=trim((string)($assignee['id']??''));if($type!==''&&$recipient!=='')$s->assign($id,$type,$recipient,max(0,$actor),true);}return $id?:null;}catch(Throwable $e){Log::add('Courses task bridge: '.$e->getMessage(),Log::WARNING,'com_decarocourses.integration');return null;}} }
